"""Publish nine explicit proposal options and a self-contained actual-city review map."""
import json,html
from pathlib import Path
from shapely.geometry import Polygon
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'artifacts/civic-plan';DATA=ROOT/'godot/assets/data'
src=json.loads((OUT/'map-source.json').read_text());level=src['level'];candidates=json.loads((OUT/'validated-candidates.json').read_text())
choices=[('P1','police',(127,-111),'Central Dumbarton station','North side of Dumbarton Avenue, between Old York Road and Wilsby Avenue. Central patrol base with direct six-metre access; preferred police option.'),('P2','police',(-21,-82),'Old York corner alternative','West of Old York Road, south of Dumbarton Avenue. Highly legible corner; conflicts with preferred fire site F1.'),('P3','police',(402,-8),'East Argonne alternative','Southeast side of Argonne Drive toward Elkader Road and North Hill Road. Strong eastern coverage, farther from the central blocks.'),('F1','fire',(-23,-87),'Old York response house','Old York Road / Dumbarton Avenue corner. Direct street access and two directions for response. Compact single-bay concept; conflicts with police alternative P2.'),('F2','fire',(291,51),'Argonne / Wilsby alternative','Southeast side of Argonne Drive by Wilsby Avenue. Direct access toward the main diagonal. Shares this potential lot with hospital alternative H2.'),('F3','fire',(331,28),'Mid-Argonne alternative','Southeast side of Argonne Drive, east of Wilsby Avenue. Separate open frontage farther along the diagonal. Shares this potential lot with H3.'),('H1','hospital',(43,20),'Wyanoke neighborhood hospital','South side of Wyanoke Avenue, east of Old York Road. Preferred compact multistorey neighborhood hospital, with direct ambulance access; existing nearby court stays.'),('H2','hospital',(294,50),'Argonne / Wilsby hospital alternative','Southeast side of Argonne Drive by Wilsby Avenue. Compact urban hospital concept with direct diagonal-road access. Mutually exclusive with fire alternative F2.'),('H3','hospital',(333,27),'Mid-Argonne hospital alternative','Southeast side of Argonne Drive east of Wilsby Avenue. Another compact urban envelope. Mutually exclusive with fire alternative F3.')]
proposals=[]
for id,service,target,title,notes in choices:
 p=dict(min((p for p in candidates if p['service']==service),key=lambda p:(p['position'][0]-target[0])**2+(p['position'][2]-target[1])**2))
 p.update(id=id,recommended=id.endswith('1'),title=title,notes=notes,status='PROPOSED ONLY',building_program='Compact 4–6 storey neighborhood hospital; no full campus or helipad' if service=='hospital' else 'Compact single-bay response house' if service=='fire' else 'Compact neighborhood police station',access_width_m=6,existing_buildings_removed=0,existing_courts_removed=0)
 p.pop('center_score',None);proposals.append(p)
for p in proposals:p['conflicts_with']=[q['id'] for q in proposals if p['id']!=q['id'] and Polygon(p['polygon']).intersects(Polygon(q['polygon']))]
payload=dict(version=1,coordinate_system=level['coordinate_system'],status='Concept alternatives only; no buildings or mission destinations created',proposals=proposals,notes=['All nine envelopes and access corridors avoid existing exported architecture, roads (except proposed access crossings), mapped parks and court footprints.','P1/F1/H1 are a compatible preferred set; other service options may share sites, explicitly listed in conflicts_with.','Geometric feasibility only: parcel boundaries/ownership are not surveyed here. Existing vegetation and yard dressing would need a later landscape review.','Hospital options are compact multistorey neighborhood facilities, not large hospital campuses. Fire options are single-bay concepts.','Envelope dimensions reserve the concept lot; actual building, accessible routes, parking, curb cuts, turning paths, grading and architecture need a separate design pass.'])
(DATA/'pen_lucy_civic_proposals.json').write_text(json.dumps(payload,indent=2),encoding='utf-8')
colors={'police':'#7cbcff','fire':'#ff967d','hospital':'#d4a1ff'}
def path(points):return 'M'+' L'.join(f'{x:.2f},{y:.2f}' for x,y in points)+' Z'
def xy(points):return [(p[0],p[2]) for p in points]
base=['<rect x="-235" y="-370" width="865" height="680" fill="#15252c"/>']
for p in level['parks']:base.append(f'<path d="{path(xy(p["polygon"]))}" fill="#314e3b"/>')
for r in level['roads']:
 pts=' '.join(f'{x:.2f},{z:.2f}' for x,z in xy(r['points']));base.append(f'<polyline points="{pts}" fill="none" stroke="#52666d" stroke-width="{r["width"]}"/>')
for b in src['buildings']:
 for ring in b['polygon']['coordinates'][:1]:base.append(f'<path d="{path(ring)}" fill="#877d71" stroke="#b4a691" stroke-width=".22"/>')
courts=json.loads((DATA/'pen_lucy_courts.json').read_text())['courts']
for c in courts:base.append(f'<path d="{path(c["footprint"])}" fill="#a18745" stroke="#cfb767" stroke-width=".55"/>')
base.append(f'<path d="{path(xy(level["site_boundary"]))}" fill="none" stroke="#516a72" stroke-width="1" stroke-dasharray="4 4"/>')
labels=[('Greenmount Ave',-170,-70,-90),('Old York Rd',0,-40,-90),('Frisby St',109,69,-90),('Wilsby Ave',263,-128,-90),('Elkader Rd',392,-140,75),('Argonne Dr',360,2,-31),('East 41st St',100,-263,-2),('Cator Ave',175,-188,-2),('Rose Hill Terrace',-98,-152,-1),('Dumbarton Ave',123,-87,-2),('Wyanoke Ave',122,-7,-3),('East 39th St',-109,101,0),('East 38th St',-85,218,0),('Ellerslie Ave',92,145,27),('Lowndes Ave',195,60,-90)]
for name,x,z,angle in labels:base.append(f'<text x="0" y="0" transform="translate({x},{z}) rotate({angle})" font-size="8" text-anchor="middle" fill="#e2e2d8" stroke="#15252c" stroke-width="2.8" paint-order="stroke">{name}</text>')
base.extend(['<text x="-204" y="-316" fill="#e5edf1" font-size="17" font-weight="bold">N ↑</text>','<path d="M-194,282 h100 m-100,-3 v6 m100,-6 v6" stroke="#b0c3c9" fill="none"/><text x="-144" y="298" fill="#b0c3c9" text-anchor="middle" font-size="9">100 metres</text>'])
base=''.join(base)
def overlay(service):
 out=[]
 for p in proposals:
  if p['service']!=service:continue
  color=colors[service];x,y,z=p['position'];label=f'{p["id"]}'+(' ★' if p['recommended'] else '')
  out.extend([f'<path d="{path(p["access"])}" fill="{color}" fill-opacity=".16" stroke="{color}" stroke-dasharray="2 2" stroke-width=".8"/>',f'<path d="{path(p["polygon"])}" fill="{color}" fill-opacity=".28" stroke="{color}" stroke-width="2"/>',f'<rect x="{x-20}" y="{z-29}" width="45" height="17" rx="3" fill="#0b1823"/>',f'<text x="{x+2}" y="{z-17}" font-size="12" font-weight="bold" text-anchor="middle" fill="{color}">{label}</text>'])
 return ''.join(out)
svgs={s:f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="-235 -340 865 650" font-family="Arial,sans-serif" role="img" aria-label="Actual Pen Lucy map with proposed {s} alternatives">{base}{overlay(s)}</svg>' for s in colors}
for service,svg in svgs.items():(OUT/f'{service}-sites.svg').write_text(svg,encoding='utf-8')
cards=[]
for p in proposals:
 cards.append(f'<article data-service="{p["service"]}"><h3 style="color:{colors[p["service"]]}">{p["id"]} {html.escape(p["title"])}'+(' <small>PREFERRED</small>' if p['recommended'] else '')+f'</h3><p>{html.escape(p["notes"])}</p><p class="meta">{p["width"]:.0f} × {p["depth"]:.0f} m envelope · 6 m access · {p["grade_range_m"]:.2f} m existing ground variation</p><p class="meta">Game x/z: {p["position"][0]:.1f}, {p["position"][2]:.1f}'+(f' · Conflicts with: {", ".join(p["conflicts_with"])}' if p['conflicts_with'] else '')+'</p></article>')
mapgroups=''.join(f'<div class="map" data-service="{s}">{svg}</div>' for s,svg in svgs.items())
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pen Lucy — proposed civic sites</title><style>*{box-sizing:border-box}body{margin:0;background:#101c23;color:#e2e7e7;font:16px/1.5 system-ui,sans-serif}header{padding:24px 32px 12px}h1{font-size:30px;line-height:1.2;margin:5px 0 10px}p{margin:8px 0}.kicker{letter-spacing:3px;color:#b9c9ce;font-size:12px}nav{display:flex;gap:9px;margin-top:18px}button{font:inherit;background:#263a45;color:#f0f4f4;border:1px solid #536e7c;padding:9px 22px;border-radius:6px;cursor:pointer}button[aria-pressed=true]{background:#e1edf3;color:#13252e}main{display:grid;grid-template-columns:minmax(600px,1fr) 400px;gap:12px;padding:8px 24px 20px}svg{width:100%;max-height:80vh}aside{padding:0 12px}article{border-top:1px solid #425761;padding:6px 0 13px}h3{font-size:18px;margin:10px 0 3px}small{font-size:10px;letter-spacing:1px}.meta{font-size:12px;color:#aec2ca}.legend{font-size:13px;color:#b9cbd1;padding:0 32px}footer{padding:18px 32px 30px;color:#b0c1c8;font-size:13px;max-width:1300px}footer p{margin:7px 0}@media(max-width:1000px){main{display:block;padding:5px}aside{padding:20px}svg{max-height:none}}[hidden]{display:none!important}</style><header><div class="kicker">PEN LUCY / CIVIC SITE STUDY</div><h1>Three services. Nine proposed options.</h1><p>Actual exported city geography. Preferred set: <b>P1 central police · F1 Old York fire · H1 Wyanoke hospital.</b></p><nav><button data-select="police">Police</button><button data-select="fire">Fire</button><button data-select="hospital">Hospital</button></nav></header><main><section>'''+mapgroups+'''</section><aside>'''+''.join(cards)+'''</aside></main><p class="legend">Tan: existing buildings · Ochre: existing courts · Green: mapped parks · Coloured envelope: proposed lot · Dotted strip: proposed road access · ★ preferred</p><footer><b>PROPOSALS ONLY — no stations built, no mission destinations changed.</b>'''+''.join('<p>'+html.escape(t)+'</p>' for t in payload['notes'])+'''<p>Coordinates: metres, x east / z south. Streets and footprints: © OpenStreetMap contributors (ODbL). Ground geometry: project export using USGS 3DEP. Game planning suggestions, not a real-world land-use claim.</p></footer><script>function select(service){document.querySelectorAll('[data-service]').forEach(e=>e.hidden=e.dataset.service!==service);document.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.select===service));}document.querySelectorAll('button').forEach(b=>b.onclick=()=>select(b.dataset.select));select('police');</script></html>'''
(OUT/'index.html').write_text(page,encoding='utf-8');(OUT/'proposal-audit.json').write_text(json.dumps(payload,indent=2),encoding='utf-8')
print('Published nine proposals, three SVG maps, self-contained HTML review.')
